    var K=function(s,q,o,a,e,t){A.push(Q("jitsu","keikaku",s,1,q,o,a,e,t));};
    X("kcd","トータルステーションは、<ruby>距離<rt>きょり</rt></ruby>と<ruby>角度<rt>かくど</rt></ruby>の<ruby>両方<rt>りょうほう</rt></ruby>を<ruby>測<rt>はか</rt></ruby>ることができる<ruby>測量機械<rt>そくりょうきかい</rt></ruby>である。",0,"Máy toàn đạc đo cả khoảng cách và góc — từ đó tính ra vị trí (tọa độ) của điểm đo, là máy chính trong trắc lượng thi công hiện nay.");
    X("kcd","<ruby>測量<rt>そくりょう</rt></ruby>の<ruby>基準点<rt>きじゅんてん</rt></ruby>は、<ruby>工事<rt>こうじ</rt></ruby>の<ruby>邪魔<rt>じゃま</rt></ruby>なら<ruby>勝手<rt>かって</rt></ruby>に<ruby>動<rt>うご</rt></ruby>かしてもよい。",1,"Mốc chuẩn là gốc của mọi vị trí/cao độ công trình — tuyệt đối không tự ý di chuyển. Nếu vướng thi công phải báo để đội trắc lượng dời mốc theo đúng quy trình đo nối.");
    X("kc","<ruby>掘削面<rt>くっさくめん</rt></ruby>の<ruby>点検<rt>てんけん</rt></ruby>は、その<ruby>日<rt>ひ</rt></ruby>の<ruby>作業<rt>さぎょう</rt></ruby>を<ruby>始<rt>はじ</rt></ruby>める<ruby>前<rt>まえ</rt></ruby>に<ruby>行<rt>おこな</rt></ruby>う。",0,"Kiểm tra mặt đào đầu ca （作業開始前点検）: nứt, rỉ nước, tình trạng chống đỡ — phát hiện bất thường phải xử lý trước khi cho người xuống làm.");
    X("kcd","<ruby>法面<rt>のりめん</rt></ruby>の<ruby>勾配<rt>こうばい</rt></ruby>は、<ruby>急<rt>きゅう</rt></ruby>なほうが<ruby>土<rt>つち</rt></ruby>の<ruby>量<rt>りょう</rt></ruby>が<ruby>少<rt>すく</rt></ruby>なくて<ruby>常<rt>つね</rt></ruby>によい。",1,"Mái dốc càng đứng càng dễ sạt — độ dốc mặt đào được quy định theo loại đất và chiều sâu, không được tự ý đào dốc hơn để giảm khối lượng.");
    X("kcd","<ruby>水準測量<rt>すいじゅんそくりょう</rt></ruby>では、<ruby>後視<rt>こうし</rt></ruby>と<ruby>前視<rt>ぜんし</rt></ruby>の<ruby>読<rt>よ</rt></ruby>みの<ruby>差<rt>さ</rt></ruby>から、<ruby>高<rt>たか</rt></ruby>さの<ruby>差<rt>さ</rt></ruby>が<ruby>分<rt>わ</rt></ruby>かる。",0,"Đúng nguyên lý thủy bình: chênh cao giữa hai điểm = số đọc sau （後視） − số đọc trước （前視）.");
    X("kc","<ruby>掘削<rt>くっさく</rt></ruby>の<ruby>深<rt>ふか</rt></ruby>さが1.5mぐらいなら、<ruby>土止<rt>どど</rt></ruby>め<ruby>支保工<rt>しほこう</rt></ruby>は<ruby>絶対<rt>ぜったい</rt></ruby>に<ruby>必要<rt>ひつよう</rt></ruby>ない。",1,"Từ khoảng 1,5m trở lên, nguyên tắc phải xét chống đỡ mặt đào （土止め支保工） — đất sạt ở độ sâu này đủ chôn vùi người gây tử vong.");
    X("kcd","<ruby>丁張<rt>ちょうは</rt></ruby>りの<ruby>杭<rt>くい</rt></ruby>や<ruby>板<rt>いた</rt></ruby>は、<ruby>工事<rt>こうじ</rt></ruby>の<ruby>基準<rt>きじゅん</rt></ruby>になるので<ruby>大切<rt>たいせつ</rt></ruby>に<ruby>扱<rt>あつか</rt></ruby>う。",0,"Cọc và ván của 丁張り mang thông tin vị trí/độ dốc thiết kế — bị xô lệch là thi công sai theo. Phải bảo vệ và tránh máy móc va chạm.");
    X("kc","<ruby>測量機械<rt>そくりょうきかい</rt></ruby>の<ruby>三脚<rt>さんきゃく</rt></ruby>は、ぐらつかないようにしっかり<ruby>立<rt>た</rt></ruby>てる。",0,"Chân máy lỏng làm máy nghiêng/ngã — vừa sai số đo vừa hỏng máy đắt tiền. Dựng chắc trên nền vững, siết chặt các khóa chân.");
    X("kcd","<ruby>標高<rt>ひょうこう</rt></ruby>とは、その<ruby>土地<rt>とち</rt></ruby>の<ruby>地面<rt>じめん</rt></ruby>から<ruby>測<rt>はか</rt></ruby>った<ruby>高<rt>たか</rt></ruby>さである。",1,"標高 là cao độ tính từ MẶT BIỂN trung bình (0m) — không phải chiều cao tính từ mặt đất tại chỗ.");
    X("kcd","<ruby>法面保護工<rt>のりめんほごこう</rt></ruby>は、<ruby>雨水<rt>あまみず</rt></ruby>などで<ruby>法面<rt>のりめん</rt></ruby>が<ruby>削<rt>けず</rt></ruby>られたり<ruby>崩<rt>くず</rt></ruby>れたりするのを<ruby>防<rt>ふせ</rt></ruby>ぐ。",0,"Gia cố mặt dốc (trồng cỏ, phun vữa, khung bê tông...) chống xói mòn do mưa và giữ ổn định lâu dài cho mái dốc.");
    X("kc","<ruby>雨<rt>あめ</rt></ruby>がたくさん<ruby>降<rt>ふ</rt></ruby>っている<ruby>日<rt>ひ</rt></ruby>も、<ruby>掘削作業<rt>くっさくさぎょう</rt></ruby>はいつも<ruby>通<rt>どお</rt></ruby>りに<ruby>続<rt>つづ</rt></ruby>けてよい。",1,"Mưa lớn làm tăng nguy cơ sạt lở và ngập hố đào — phải dừng hoặc hạn chế đào, tăng cường kiểm tra và thoát nước theo chỉ thị phụ trách.");
    X("kcd","<ruby>測量<rt>そくりょう</rt></ruby>の<ruby>読<rt>よ</rt></ruby>みは、その<ruby>場<rt>ば</rt></ruby>で<ruby>記録<rt>きろく</rt></ruby>し、<ruby>読<rt>よ</rt></ruby>み<ruby>上<rt>あ</rt></ruby>げて<ruby>確認<rt>かくにん</rt></ruby>する。",0,"Số đo phải ghi ngay tại chỗ và đọc lại đối chiếu （復唱確認） — ghi nhớ rồi về mới chép rất dễ sai số, mà số liệu trắc lượng sai là thi công sai hàng loạt.");
    G("kcd","トータルステーションで<ruby>測<rt>はか</rt></ruby>ることができるものはどれですか。",["<ruby>距離<rt>きょり</rt></ruby>と<ruby>角度<rt>かくど</rt></ruby>","<ruby>温度<rt>おんど</rt></ruby>と<ruby>湿度<rt>しつど</rt></ruby>","<ruby>重<rt>おも</rt></ruby>さと<ruby>体積<rt>たいせき</rt></ruby>"],0,"Toàn đạc = đo góc + đo khoảng cách điện tử, tính ra tọa độ và cao độ của điểm cần xác định.");
    G("kcd","<ruby>標高<rt>ひょうこう</rt></ruby>とは、<ruby>何<rt>なに</rt></ruby>からの<ruby>高<rt>たか</rt></ruby>さですか。",["<ruby>海面<rt>かいめん</rt></ruby>（<ruby>平均海面<rt>へいきんかいめん</rt></ruby>）","<ruby>近<rt>ちか</rt></ruby>くの<ruby>建物<rt>たてもの</rt></ruby>","<ruby>地面<rt>じめん</rt></ruby>の<ruby>一番低<rt>いちばんひく</rt></ruby>い<ruby>場所<rt>ばしょ</rt></ruby>"],0,"Mọi cao độ công trình đều quy về mực nước biển trung bình — nhờ vậy các công trình ở nơi khác nhau vẫn khớp cao độ với nhau.");
    G("kcd","レベル<ruby>測量<rt>そくりょう</rt></ruby>の「<ruby>後視<rt>こうし</rt></ruby>（バックサイト）」とは、どのような<ruby>測定<rt>そくてい</rt></ruby>ですか。",["<ruby>標高<rt>ひょうこう</rt></ruby>の<ruby>分<rt>わ</rt></ruby>かっている<ruby>点<rt>てん</rt></ruby>を<ruby>測<rt>はか</rt></ruby>ること","<ruby>後<rt>うし</rt></ruby>ろを<ruby>振<rt>ふ</rt></ruby>り<ruby>返<rt>かえ</rt></ruby>って<ruby>見<rt>み</rt></ruby>ること","<ruby>最後<rt>さいご</rt></ruby>に<ruby>測<rt>はか</rt></ruby>ること"],0,"後視 là số đọc trên mia dựng tại điểm ĐÃ BIẾT cao độ (BM) — từ đó tính được cao độ của đường ngắm (器械高）.");
    G("kc","<ruby>掘削作業<rt>くっさくさぎょう</rt></ruby>を<ruby>始<rt>はじ</rt></ruby>める<ruby>前<rt>まえ</rt></ruby>の<ruby>点検項目<rt>てんけんこうもく</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>法面<rt>のりめん</rt></ruby>の<ruby>亀裂<rt>きれつ</rt></ruby>・<ruby>湧水<rt>ゆうすい</rt></ruby>・<ruby>土止<rt>どど</rt></ruby>めの<ruby>状態<rt>じょうたい</rt></ruby>","ダンプの<ruby>台数<rt>だいすう</rt></ruby>だけ","<ruby>昼食<rt>ちゅうしょく</rt></ruby>の<ruby>場所<rt>ばしょ</rt></ruby>"],0,"Ba điểm kiểm tra sống còn trước khi xuống hố đào: mặt dốc có nứt không, có nước rỉ không, hệ chống đỡ có nguyên vẹn không.");
    G("kcd","<ruby>掘削面<rt>くっさくめん</rt></ruby>の<ruby>勾配<rt>こうばい</rt></ruby>を<ruby>決<rt>き</rt></ruby>めるときに<ruby>関係<rt>かんけい</rt></ruby>するものはどれですか。",["<ruby>土<rt>つち</rt></ruby>の<ruby>種類<rt>しゅるい</rt></ruby>と<ruby>掘削<rt>くっさく</rt></ruby>の<ruby>深<rt>ふか</rt></ruby>さ","<ruby>天気<rt>てんき</rt></ruby>だけ","<ruby>機械<rt>きかい</rt></ruby>の<ruby>色<rt>いろ</rt></ruby>"],0,"Đất cát rời cần mái thoải hơn đất sét dính; đào càng sâu mái càng phải thoải hoặc phải chống đỡ — quy định theo bảng an toàn.");
    G("kcd","レベル<ruby>測量<rt>そくりょう</rt></ruby>の「<ruby>器械高<rt>きかいこう</rt></ruby>」の<ruby>求<rt>もと</rt></ruby>め<ruby>方<rt>かた</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["BMの<ruby>標高<rt>ひょうこう</rt></ruby>に<ruby>後視<rt>こうし</rt></ruby>を<ruby>足<rt>た</rt></ruby>す","BMの<ruby>標高<rt>ひょうこう</rt></ruby>から<ruby>後視<rt>こうし</rt></ruby>を<ruby>引<rt>ひ</rt></ruby>く","<ruby>後視<rt>こうし</rt></ruby>と<ruby>前視<rt>ぜんし</rt></ruby>を<ruby>足<rt>た</rt></ruby>す"],0,"器械高 (cao độ đường ngắm) = cao độ BM + số đọc sau. Sau đó cao độ điểm bất kỳ = 器械高 − số đọc trước tại điểm đó.");
    G("kc","<ruby>土止<rt>どど</rt></ruby>め<ruby>支保工<rt>しほこう</rt></ruby>の<ruby>目的<rt>もくてき</rt></ruby>はどれですか。",["<ruby>掘削面<rt>くっさくめん</rt></ruby>の<ruby>崩壊<rt>ほうかい</rt></ruby>を<ruby>防<rt>ふせ</rt></ruby>いで、<ruby>作業員<rt>さぎょういん</rt></ruby>を<ruby>守<rt>まも</rt></ruby>るため","<ruby>掘削<rt>くっさく</rt></ruby>を<ruby>速<rt>はや</rt></ruby>くするため","<ruby>土<rt>つち</rt></ruby>を<ruby>運<rt>はこ</rt></ruby>びやすくするため"],0,"Ván chống + thanh chống đỡ mặt đào đứng để đất không sập xuống người đang làm việc trong hố — thiết bị bảo vệ tính mạng trực tiếp.");
    G("kcd","<ruby>基準点<rt>きじゅんてん</rt></ruby>の<ruby>杭<rt>くい</rt></ruby>の<ruby>扱<rt>あつか</rt></ruby>いとして、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>周<rt>まわ</rt></ruby>りに<ruby>目印<rt>めじるし</rt></ruby>を<ruby>付<rt>つ</rt></ruby>けて<ruby>守<rt>まも</rt></ruby>り、<ruby>動<rt>うご</rt></ruby>かさない","<ruby>邪魔<rt>じゃま</rt></ruby>なら<ruby>抜<rt>ぬ</rt></ruby>いて<ruby>後<rt>あと</rt></ruby>で<ruby>戻<rt>もど</rt></ruby>す","<ruby>上<rt>うえ</rt></ruby>に<ruby>材料<rt>ざいりょう</rt></ruby>を<ruby>置<rt>お</rt></ruby>く"],0,"Mốc chuẩn phải được bảo vệ bằng rào/dấu hiệu rõ ràng — mất mốc là mất gốc tọa độ của cả khu vực thi công.");
    G("kcd","レベルを<ruby>据<rt>す</rt></ruby>えるときの<ruby>作業<rt>さぎょう</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>気泡<rt>きほう</rt></ruby>を<ruby>見<rt>み</rt></ruby>ながら、<ruby>機械<rt>きかい</rt></ruby>が<ruby>水平<rt>すいへい</rt></ruby>になるように<ruby>調整<rt>ちょうせい</rt></ruby>する","<ruby>傾<rt>かたむ</rt></ruby>いていてもそのまま<ruby>測<rt>はか</rt></ruby>る","<ruby>三脚<rt>さんきゃく</rt></ruby>は<ruby>短<rt>みじか</rt></ruby>いほうがよい"],0,"Máy thủy bình chỉ đo đúng khi đường ngắm thật sự nằm ngang — phải chỉnh bọt thủy tròn vào giữa trước mỗi lần đặt máy.");
    G("kc","<ruby>大雨<rt>おおあめ</rt></ruby>の<ruby>後<rt>あと</rt></ruby>に<ruby>作業<rt>さぎょう</rt></ruby>を<ruby>再開<rt>さいかい</rt></ruby>するとき、まず<ruby>行<rt>おこな</rt></ruby>うことはどれですか。",["<ruby>法面<rt>のりめん</rt></ruby>や<ruby>土止<rt>どど</rt></ruby>めを<ruby>点検<rt>てんけん</rt></ruby>して、<ruby>安全<rt>あんぜん</rt></ruby>を<ruby>確認<rt>かくにん</rt></ruby>する","すぐに<ruby>掘削<rt>くっさく</rt></ruby>を<ruby>始<rt>はじ</rt></ruby>める","<ruby>水<rt>みず</rt></ruby>が<ruby>引<rt>ひ</rt></ruby>くのを<ruby>待<rt>ま</rt></ruby>たずに<ruby>入<rt>はい</rt></ruby>る"],0,"Sau mưa lớn, đất yếu đi rõ rệt — chỉ tái khởi công sau khi chỉ huy kiểm tra mặt đào, chống đỡ và hệ thoát nước.");
    G("kcd","<ruby>勾配<rt>こうばい</rt></ruby>「1：1.5」の<ruby>意味<rt>いみ</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>縦<rt>たて</rt></ruby>に1<ruby>下<rt>さ</rt></ruby>がると、<ruby>横<rt>よこ</rt></ruby>に1.5<ruby>進<rt>すす</rt></ruby>む<ruby>傾<rt>かたむ</rt></ruby>き","<ruby>長<rt>なが</rt></ruby>さ1.5mの<ruby>板<rt>いた</rt></ruby>を<ruby>使<rt>つか</rt></ruby>うこと","1<ruby>日<rt>にち</rt></ruby>に1.5m<ruby>掘<rt>ほ</rt></ruby>ること"],0,"Ký hiệu độ dốc 1:1,5 = tỉ lệ đứng:ngang — cứ xuống 1m theo chiều đứng thì mặt dốc lùi 1,5m theo chiều ngang.");
    G("kcd","<ruby>現場<rt>げんば</rt></ruby>で<ruby>距離<rt>きょり</rt></ruby>を<ruby>測<rt>はか</rt></ruby>る<ruby>基本<rt>きほん</rt></ruby>の<ruby>道具<rt>どうぐ</rt></ruby>はどれですか。",["スチールテープ（<ruby>巻尺<rt>まきじゃく</rt></ruby>）","レベル","スタッフ"],0,"Thước cuộn thép là dụng cụ đo khoảng cách cơ bản tại hiện trường; レベル và スタッフ là bộ đo cao độ.");
    G("kc","<ruby>作業主任者<rt>さぎょうしゅにんしゃ</rt></ruby>の<ruby>役割<rt>やくわり</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>作業<rt>さぎょう</rt></ruby>の<ruby>方法<rt>ほうほう</rt></ruby>を<ruby>決<rt>き</rt></ruby>めて<ruby>作業員<rt>さぎょういん</rt></ruby>を<ruby>直接指揮<rt>ちょくせつしき</rt></ruby>し、<ruby>安全<rt>あんぜん</rt></ruby>を<ruby>守<rt>まも</rt></ruby>る","<ruby>材料<rt>ざいりょう</rt></ruby>の<ruby>注文<rt>ちゅうもん</rt></ruby>だけをする","<ruby>給料<rt>きゅうりょう</rt></ruby>を<ruby>計算<rt>けいさん</rt></ruby>する"],0,"Chỉ huy công tác (ví dụ đào đất, chống đỡ) là người có chứng chỉ, quyết định phương pháp làm và trực tiếp chỉ huy nhóm để phòng tai nạn.");
    G("kcd","<ruby>法面<rt>のりめん</rt></ruby>を<ruby>雨<rt>あめ</rt></ruby>から<ruby>守<rt>まも</rt></ruby>る<ruby>方法<rt>ほうほう</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["シートで<ruby>覆<rt>おお</rt></ruby>ったり、<ruby>上<rt>うえ</rt></ruby>に<ruby>排水溝<rt>はいすいこう</rt></ruby>を<ruby>設<rt>もう</rt></ruby>けたりする","<ruby>水<rt>みず</rt></ruby>をたくさんかける","そのままにする"],0,"Hai cách cơ bản: chặn nước chảy vào mặt dốc bằng rãnh thoát phía trên, và phủ bạt mặt dốc để mưa không xói trực tiếp.");
    G("kcd","スタッフの<ruby>読<rt>よ</rt></ruby>み<ruby>方<rt>かた</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>機械<rt>きかい</rt></ruby>の<ruby>横線<rt>よこせん</rt></ruby>に<ruby>合<rt>あ</rt></ruby>った<ruby>目盛<rt>めも</rt></ruby>りを<ruby>読<rt>よ</rt></ruby>む","<ruby>一番上<rt>いちばんうえ</rt></ruby>の<ruby>目盛<rt>めも</rt></ruby>りを<ruby>読<rt>よ</rt></ruby>む","<ruby>色<rt>いろ</rt></ruby>の<ruby>変<rt>か</rt></ruby>わる<ruby>場所<rt>ばしょ</rt></ruby>を<ruby>読<rt>よ</rt></ruby>む"],0,"Đọc số tại vạch chia trùng với vạch ngang giữa của kính ngắm — đó là chiều cao từ chân mia tới đường ngắm.");
    G("kc","<ruby>硫化水素<rt>りゅうかすいそ</rt></ruby>が<ruby>発生<rt>はっせい</rt></ruby>しやすい<ruby>場所<rt>ばしょ</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>下水<rt>げすい</rt></ruby>や<ruby>汚水<rt>おすい</rt></ruby>のたまる<ruby>場所<rt>ばしょ</rt></ruby>","<ruby>屋外<rt>おくがい</rt></ruby>の<ruby>広<rt>ひろ</rt></ruby>い<ruby>場所<rt>ばしょ</rt></ruby>","<ruby>新<rt>あたら</rt></ruby>しいコンクリートの<ruby>上<rt>うえ</rt></ruby>"],0,"Khí H₂S (mùi trứng thối) sinh ra từ nước thải phân hủy — ở hố ga, bể chứa nước thải, khí này nặng hơn không khí và đọng ở đáy, gây ngộ độc rất nhanh.");
    G("kcd","<ruby>現場<rt>げんば</rt></ruby>の「<ruby>仮<rt>かり</rt></ruby>BM」とは、どのようなものですか。",["<ruby>工事中<rt>こうじちゅう</rt></ruby>に<ruby>使<rt>つか</rt></ruby>うため、BMから<ruby>高<rt>たか</rt></ruby>さを<ruby>移<rt>うつ</rt></ruby>して<ruby>設<rt>もう</rt></ruby>けた<ruby>臨時<rt>りんじ</rt></ruby>の<ruby>基準点<rt>きじゅんてん</rt></ruby>","<ruby>休憩<rt>きゅうけい</rt></ruby>の<ruby>場所<rt>ばしょ</rt></ruby>","<ruby>材料<rt>ざいりょう</rt></ruby>を<ruby>置<rt>お</rt></ruby>く<ruby>場所<rt>ばしょ</rt></ruby>"],0,"Mốc phụ （仮BM) được dẫn cao độ từ mốc gốc tới vị trí thuận tiện trong công trường để dùng hằng ngày — phải chọn điểm chắc chắn, không bị thi công làm xê dịch.");
    G("kcd","「<ruby>明<rt>あ</rt></ruby>かり<ruby>掘削<rt>くっさく</rt></ruby>」とは、どのような<ruby>掘削<rt>くっさく</rt></ruby>ですか。",["<ruby>地表面<rt>ちひょうめん</rt></ruby>から<ruby>直接<rt>ちょくせつ</rt></ruby><ruby>掘<rt>ほ</rt></ruby>る、トンネルではない<ruby>掘削<rt>くっさく</rt></ruby>","<ruby>夜<rt>よる</rt></ruby>に<ruby>明<rt>あか</rt></ruby>るくして<ruby>掘<rt>ほ</rt></ruby>ること","<ruby>小<rt>ちい</rt></ruby>さい<ruby>穴<rt>あな</rt></ruby>を<ruby>掘<rt>ほ</rt></ruby>ること"],0,"Đào hở (open-cut): đào từ mặt đất xuống dưới trời mở — đối nghĩa với đào hầm （トンネル掘削）.");
    J("kcd","この<ruby>状況<rt>じょうきょう</rt></ruby>で、<ruby>行<rt>おこな</rt></ruby>うべきことはどれですか。",["<ruby>囲<rt>かこ</rt></ruby>いや<ruby>目印<rt>めじるし</rt></ruby>で<ruby>守<rt>まも</rt></ruby>り、<ruby>移<rt>うつ</rt></ruby>す<ruby>必要<rt>ひつよう</rt></ruby>があれば<ruby>責任者<rt>せきにんしゃ</rt></ruby>に<ruby>相談<rt>そうだん</rt></ruby>する","そのまま<ruby>作業<rt>さぎょう</rt></ruby>する","<ruby>自分<rt>じぶん</rt></ruby>で<ruby>少<rt>すこ</rt></ruby>し<ruby>動<rt>うご</rt></ruby>かす"],0,"Mốc chuẩn nằm trong vùng máy hoạt động phải được rào bảo vệ ngay; việc dời mốc chỉ do trắc lượng thực hiện bằng đo nối chính xác.","<ruby>測量<rt>そくりょう</rt></ruby>の<ruby>基準杭<rt>きじゅんぐい</rt></ruby>が、<ruby>重機<rt>じゅうき</rt></ruby>が<ruby>通<rt>とお</rt></ruby>る<ruby>場所<rt>ばしょ</rt></ruby>にあります。");
    J("kcd","この<ruby>状況<rt>じょうきょう</rt></ruby>で、<ruby>行<rt>おこな</rt></ruby>うべきことはどれですか。",["<ruby>機械<rt>きかい</rt></ruby>の<ruby>据<rt>す</rt></ruby>え<ruby>付<rt>つ</rt></ruby>けを<ruby>確認<rt>かくにん</rt></ruby>して、<ruby>測<rt>はか</rt></ruby>り<ruby>直<rt>なお</rt></ruby>す","そのまま<ruby>記録<rt>きろく</rt></ruby>する","<ruby>数値<rt>すうち</rt></ruby>を<ruby>平均<rt>へいきん</rt></ruby>して<ruby>使<rt>つか</rt></ruby>う"],0,"Số đọc sau lệch bất thường nghĩa là máy bị xê dịch hoặc nhầm mốc — phải kiểm tra lại vị trí máy và đo lại từ đầu, không dùng số liệu đáng ngờ.","BMの<ruby>後視<rt>こうし</rt></ruby>の<ruby>読<rt>よ</rt></ruby>みが、いつもと<ruby>大<rt>おお</rt></ruby>きく<ruby>違<rt>ちが</rt></ruby>います。");
    J("kc","この<ruby>状況<rt>じょうきょう</rt></ruby>で、まず<ruby>行<rt>おこな</rt></ruby>うべきことはどれですか。",["<ruby>下<rt>した</rt></ruby>の<ruby>作業<rt>さぎょう</rt></ruby>を<ruby>止<rt>と</rt></ruby>めて、<ruby>法面<rt>のりめん</rt></ruby>を<ruby>点検<rt>てんけん</rt></ruby>する","そのまま<ruby>作業<rt>さぎょう</rt></ruby>を<ruby>続<rt>つづ</rt></ruby>ける","<ruby>小石<rt>こいし</rt></ruby>を<ruby>手<rt>て</rt></ruby>で<ruby>払<rt>はら</rt></ruby>う"],0,"Đá nhỏ bắt đầu rơi là tín hiệu mặt dốc đang mất ổn định — dừng ngay công việc phía dưới, đưa người ra và kiểm tra toàn bộ mặt dốc.","<ruby>法面<rt>のりめん</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>から、<ruby>小石<rt>こいし</rt></ruby>がパラパラと<ruby>落<rt>お</rt></ruby>ちてきました。<ruby>下<rt>した</rt></ruby>では<ruby>作業<rt>さぎょう</rt></ruby>をしています。");
    J("kcd","この<ruby>状況<rt>じょうきょう</rt></ruby>での<ruby>対応<rt>たいおう</rt></ruby>として、<ruby>正<rt>ただ</rt></ruby>しいものはどれですか。",["<ruby>責任者<rt>せきにんしゃ</rt></ruby>に<ruby>報告<rt>ほうこく</rt></ruby>して、<ruby>土止<rt>どど</rt></ruby>めの<ruby>指示<rt>しじ</rt></ruby>を<ruby>受<rt>う</rt></ruby>ける","そのまま<ruby>掘<rt>ほ</rt></ruby>り<ruby>続<rt>つづ</rt></ruby>ける","<ruby>壁<rt>かべ</rt></ruby>を<ruby>手<rt>て</rt></ruby>で<ruby>押<rt>お</rt></ruby>さえる"],0,"Khi độ sâu tiến tới ngưỡng phải chống đỡ, dừng và báo để lắp 土止め支保工 theo chỉ thị — tự đào tiếp qua ngưỡng là vi phạm an toàn nghiêm trọng.","<ruby>掘削<rt>くっさく</rt></ruby>が<ruby>深<rt>ふか</rt></ruby>くなり、<ruby>土止<rt>どど</rt></ruby>めが<ruby>必要<rt>ひつよう</rt></ruby>な<ruby>深<rt>ふか</rt></ruby>さに<ruby>近<rt>ちか</rt></ruby>づいてきました。");
